  const priorDeferredKeys = partition3.fresh.length > planCap ? await readRecentTicks(workspaceId, 1, { status: "ran" }).then((t12) => t12[0]?.deferredKeys ?? []).catch(() => []) : [];
  const plan = planWatchdogCaptures(partition3.fresh, { ...opts, priorDeferredKeys });
  const captured = [];
